  auto refuse=[this](const QString& message){session_.remove("pendingSketchMove");view_->showSketchDraft(evaluateSketchDraft(session_["draftSketch"].toObject()));syncSketchRotateControls(message);refreshSketchControls();return failure("sketch_rotate_failed",message);};
  auto base=session_["draftSketch"].toObject(),inputs=a;const auto prior=session_["pendingSketchMove"].toObject();if(a["groupId"].toString().isEmpty() && prior["rotate"].toBool() && prior["base"]==base){const auto groups=prior["draft"].toObject()["parameters"].toObject()["rotateGroups"].toArray();if(!groups.isEmpty()){base=prior["draft"].toObject();inputs["groupId"]=groups.first().toObject()["id"];}}
  const auto solved=SketchGeometry::retainedRotate(base,inputs,session_["projectionContext"].toObject());if(!solved.ok)return refuse(solved.error);
  if(!session_["inputs"].toObject()["sketchId"].toString().isEmpty())try{GeometryKernel::evaluateDocument(SketchGeometry::replaceFeature(document_->authored(),solved.feature));}catch(const std::exception& e){return refuse(QString::fromUtf8(e.what()));}
  const auto group=solved.feature["parameters"].toObject()["rotateGroups"].toArray().first().toObject();session_["pendingSketchMove"]=QJsonObject{{"rotate",true},{"base",session_["draftSketch"]},{"draft",solved.feature},{"diagnostics",solved.diagnostics},{"entityIds",group["entityIds"]}};
